import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import axios from 'axios';

const Dashboard = () => {
  const [vehicles, setVehicles] = useState([]);
  const [category, setCategory] = useState('campus'); // campus, taxi, outstation

  useEffect(() => {
    // Fetch vehicles from real backend
    axios.get('http://localhost:5000/api/vehicles')
      .then(res => setVehicles(res.data))
      .catch(err => console.error("Error fetching vehicles:", err));
  }, []);

  // Filter vehicles by category
  const filteredVehicles = vehicles.filter(v => {
    if (category === 'campus') return ['ebike', 'scooter', 'bike'].includes(v.type);
    if (category === 'taxi') return v.type === 'bike-taxi';
    if (category === 'outstation') return v.type === 'car-rental';
    return true;
  });

  return (
    <div style={{ display: 'flex' }}>
      {/* Sidebar */}
      <div className="sidebar">
        <div className="logo"><i className="fa-solid fa-bolt text-primary"></i> VRX Dashboard</div>
        <ul>
          <li><Link to="/dashboard" className="active"><i className="fa-solid fa-gauge"></i> Overview</Link></li>
          <li><Link to="/dashboard"><i className="fa-solid fa-motorcycle"></i> My Rides</Link></li>
          <li><Link to="/dashboard"><i className="fa-solid fa-wallet"></i> Wallet</Link></li>
          <li><Link to="/dashboard"><i className="fa-solid fa-user"></i> Profile</Link></li>
          <li><Link to="/"><i className="fa-solid fa-arrow-right-from-bracket"></i> Logout</Link></li>
        </ul>
      </div>

      {/* Main Content */}
      <div className="main-content" style={{ flex: 1, backgroundColor: 'var(--light)', minHeight: '100vh' }}>
        <div className="d-flex justify-content-between align-items-center mb-5 bg-white p-3 rounded-4 shadow-sm">
          <h3 className="fw-bold m-0">Welcome back, Student! 👋</h3>
          <div className="d-flex align-items-center gap-3">
            <span className="badge bg-success bg-opacity-10 text-success px-3 py-2 rounded-pill">
              <i className="fa-solid fa-wallet me-2"></i>Balance: ₹500
            </span>
            <img src="https://ui-avatars.com/api/?name=Student&background=2563EB&color=fff" className="rounded-circle" width="45" alt="User" />
          </div>
        </div>

        <div className="row g-4 mb-5">
          <div className="col-md-4">
            <div className="bg-white p-4 rounded-4 shadow-sm d-flex align-items-center gap-3">
              <div style={{ width: '60px', height: '60px', borderRadius: '15px', background: 'rgba(37, 99, 235, 0.1)', color: 'var(--primary)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '24px' }}>
                <i className="fa-solid fa-route"></i>
              </div>
              <div>
                <h6 className="text-muted mb-1">Total Rides</h6>
                <h3 className="fw-bold m-0">12</h3>
              </div>
            </div>
          </div>
          <div className="col-md-4">
            <div className="bg-white p-4 rounded-4 shadow-sm d-flex align-items-center gap-3">
              <div style={{ width: '60px', height: '60px', borderRadius: '15px', background: 'rgba(16, 185, 129, 0.1)', color: 'var(--accent)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '24px' }}>
                <i className="fa-solid fa-motorcycle"></i>
              </div>
              <div>
                <h6 className="text-muted mb-1">Distance Travelled</h6>
                <h3 className="fw-bold m-0">45 km</h3>
              </div>
            </div>
          </div>
        </div>

        {/* Uber-like Category Selector */}
        <div className="d-flex gap-3 mb-4">
          <button className={`btn rounded-pill fw-bold ${category === 'campus' ? 'btn-dark' : 'btn-outline-dark'}`} onClick={() => setCategory('campus')}><i className="fa-solid fa-bolt me-2"></i> Campus Scooters</button>
          <button className={`btn rounded-pill fw-bold ${category === 'taxi' ? 'btn-dark' : 'btn-outline-dark'}`} onClick={() => setCategory('taxi')}><i className="fa-solid fa-motorcycle me-2"></i> Bike Taxi</button>
          <button className={`btn rounded-pill fw-bold ${category === 'outstation' ? 'btn-dark' : 'btn-outline-dark'}`} onClick={() => setCategory('outstation')}><i className="fa-solid fa-car me-2"></i> Outstation Cabs</button>
        </div>

        <h4 className="fw-bold mb-4">Available Near You</h4>
        <div className="row g-4">
          {filteredVehicles.map((v, i) => {
            const icon = v.type === 'car-rental' ? 'fa-car' : (v.type === 'bike-taxi' ? 'fa-motorcycle' : 'fa-bolt');
            return (
              <div className="col-md-4" key={i}>
                <div className="bg-white rounded-4 overflow-hidden shadow-sm border border-light">
                  <div style={{ height: '150px', background: 'linear-gradient(135deg, #F1F5F9, #E2E8F0)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '4rem', color: '#94A3B8' }}>
                    <i className={`fa-solid ${icon}`}></i>
                  </div>
                  <div className="p-4">
                    <div className="d-flex justify-content-between align-items-center mb-2">
                      <h5 className="fw-bold m-0">{v.model}</h5>
                      <span className="text-primary fw-bold">₹{v.pricePerHour}/hr</span>
                    </div>
                    <div className="text-muted small mb-3">
                      <i className="fa-solid fa-location-dot text-danger me-1"></i> {v.currentLocation?.address || 'Near you'}
                    </div>
                    <div className="text-muted small mb-4 d-flex gap-3 flex-wrap">
                      <span className="badge bg-light text-dark"><i className="fa-solid fa-tag me-1"></i>{v.type}</span>
                      {v.batteryLevel && <span className="badge bg-light text-success"><i className="fa-solid fa-battery-full me-1"></i>{v.batteryLevel}%</span>}
                      {v.features?.map(f => <span key={f} className="badge bg-light text-primary">{f}</span>)}
                    </div>
                    <button className="btn btn-primary-custom w-100 rounded-pill"><i className="fa-solid fa-qrcode me-2"></i> Book & Unlock</button>
                  </div>
                </div>
              </div>
            );
          })}
          {filteredVehicles.length === 0 && (
            <div className="col-12 text-center text-muted p-5">
              <i className="fa-solid fa-magnifying-glass fs-1 mb-3"></i>
              <p>No vehicles found in this category right now.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
